	}
}

// Usage 是一次成功的承诺使用记录。
type Usage struct {
	// ID 是全局唯一的使用编号。
	ID string
	// CommitmentID 是被扣减的承诺编号。
	CommitmentID string
	// Quantity 是本次使用的正整数数量。
