124	// TestRequestViewConfirmsExpiryIrreversibly 验证请求明细查询也是到期确认入口。
125	func TestRequestViewConfirmsExpiryIrreversibly(t *testing.T) {
126		s := expStore(t, 5)
127		noon := t0.Add(10 * day)
128		before := noon.Add(-time.Minute)
129		after := noon.Add(time.Minute)
130		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
131			t.Fatalf("reserve: %v", err)
132		}
133	
134		v, err := s.RequestView("r1", after)
135		if err != nil {
136			t.Fatalf("request view after: %v", err)
137		}
138		if v.Commitments[0].Status != CommitmentExpired {
139			t.Fatalf("status after expiry: %q", v.Commitments[0].Status)
140		}
141		// 回退时刻：仍到期。
142		v2, _ := s.RequestView("r1", before)
143		if v2.Commitments[0].Status != CommitmentExpired {
144			t.Fatalf("status rolled back to %q, want expired", v2.Commitments[0].Status)
145		}
146		st, _ := s.PartStatus("part1", before)
147		if st.ActiveOccupied != 0 || st.Committable != 5 {
148			t.Fatalf("confirmed expiry still occupies at rollback: %+v", st)
149		}
150		// 取回当前承诺后按较早时刻查看，状态保持到期。
151		c, _ := s.Commitment("jia")
152		if c.Status(before) != CommitmentExpired {
153			t.Fatalf("commitment Status at earlier time = %q, want expired", c.Status(before))
154		}
155	}
156	
157	// TestUseConfirmsExpiryIrreversibly 验证针对已知承诺的新使用判断确认到期，
158	// 一经确认，回退时刻的新使用也一律拒绝。
159	func TestUseConfirmsExpiryIrreversibly(t *testing.T) {
160		s := expStore(t, 5)
161		noon := t0.Add(10 * day)
162		before := noon.Add(-time.Minute)
163		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
164			t.Fatalf("reserve: %v", err)
165		}
166		// 到期时刻的新使用：确认到期并拒绝。
167		if _, err := s.Use("u1", "jia", 1, noon); !errors.Is(err, ErrCommitmentClosed) {
168			t.Fatalf("use at expiry: got %v, want ErrCommitmentClosed", err)
169		}
170		// 回退时刻的新使用：仍拒绝，且不扣减。
171		if _, err := s.Use("u2", "jia", 1, before); !errors.Is(err, ErrCommitmentClosed) {
172			t.Fatalf("use after rollback: got %v, want ErrCommitmentClosed", err)
173		}
174		c, _ := s.Commitment("jia")
175		if c.Used != 0 || !c.Expired {
176			t.Fatalf("jia changed by rejected uses: %+v", c)
177		}
178		st, _ := s.PartStatus("part1", before)
179		if st.PhysicalRemaining != 5 || st.ActiveOccupied != 0 || st.Committable != 5 {
180			t.Fatalf("stock after confirmed expiry: %+v", st)
181		}
182	}
183	
184	// TestExpiryBoundaryOneSecond 验证到期时刻前一秒仍可用，到期时刻确认后
185	// 回退到前一秒也不再占用，且只释放未用部分、不补回已扣实物。
186	func TestExpiryBoundaryOneSecond(t *testing.T) {
187		s := expStore(t, 5)
188		noon := t0.Add(10 * day)
189		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, noon.Add(-time.Minute)); err != nil {
190			t.Fatalf("reserve: %v", err)
191		}
192		// 到期前一秒：仍有效，使用一件。
193		if _, err := s.Use("u1", "jia", 1, noon.Add(-time.Second)); err != nil {
194			t.Fatalf("use one second before expiry: %v", err)
195		}
196		// 到期时刻：确认到期并拒绝。
197		if _, err := s.Use("u2", "jia", 1, noon); !errors.Is(err, ErrCommitmentClosed) {
198			t.Fatalf("use at expiry: %v", err)
199		}
200		// 回退到前一秒：未用四件已永久释放，实物因已用一件剩四件。
201		st, _ := s.PartStatus("part1", noon.Add(-time.Second))
202		if st.PhysicalRemaining != 4 || st.ActiveOccupied != 0 || st.Committable != 4 {
203			t.Fatalf("rollback after partial use+expiry: %+v", st)
204		}
205		d, _ := detailByID(st, "jia")
206		if d.Status != CommitmentExpired || d.OriginalQuantity != 5 ||
207			d.UsedQuantity != 1 || d.RemainingQuantity != 4 {
208			t.Fatalf("jia detail: %+v", d)
209		}
210	}
211	
212	// TestReserveRetryDoesNotConfirmExpiry 验证原样预留重试只取回首次快照，
213	// 不借本次时刻确认到期，承诺在较早时刻仍开放使用。
214	func TestReserveRetryDoesNotConfirmExpiry(t *testing.T) {
215		s := expStore(t, 5)
216		noon := t0.Add(10 * day)
217		before := noon.Add(-time.Minute)
218		after := noon.Add(time.Minute)
219		first, err := s.Reserve("jia", "r1", "part1", 5, noon, before)
220		if err != nil {
221			t.Fatalf("reserve: %v", err)
222		}
223		// 晚于到期时刻原样重试：仍返回首次快照，不确认到期。
224		got, err := s.Reserve("jia", "r1", "part1", 5, noon, after)
225		if err != nil {
226			t.Fatalf("idempotent retry after expiry: %v", err)
227		}
228		if got != first || got.Expired {
229			t.Fatalf("retry = %+v, want first %+v", got, first)
230		}
231		c, _ := s.Commitment("jia")
232		if c.Expired {
233			t.Fatal("idempotent retry confirmed expiry")
234		}
235		// 较早时刻仍有效、占用五件。
236		st, _ := s.PartStatus("part1", before)
237		if st.ActiveOccupied != 5 || st.Committable != 0 {
238			t.Fatalf("retry released occupancy: %+v", st)
239		}
240		if d, _ := detailByID(st, "jia"); d.Status != CommitmentActive {
241			t.Fatalf("jia status = %q, want active", d.Status)
242		}
243		// 较早时刻新使用仍成功：重试没有关闭承诺。
244		if _, err := s.Use("u1", "jia", 1, before); err != nil {
245			t.Fatalf("use after non-confirming retry: %v", err)
246		}
247	}
248	
249	// TestUseRetryDoesNotConfirmExpiry 验证原样使用重试只取回首次使用结果，
250	// 不确认到期；只有新使用才会确认。
251	func TestUseRetryDoesNotConfirmExpiry(t *testing.T) {
252		s := expStore(t, 5)
253		noon := t0.Add(10 * day)
254		before := noon.Add(-time.Minute)
255		after := noon.Add(time.Minute)
256		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
257			t.Fatalf("reserve: %v", err)
258		}
259		u1, err := s.Use("u1", "jia", 2, before)
260		if err != nil {
261			t.Fatalf("use: %v", err)
262		}
263		// 晚于到期时刻原样重试：取回首次结果，不确认到期、不再次扣减。
264		got, err := s.Use("u1", "jia", 2, after)
265		if err != nil || got != u1 {
266			t.Fatalf("use retry after expiry: %+v err %v", got, err)
267		}
268		c, _ := s.Commitment("jia")
269		if c.Used != 2 || c.Expired {
270			t.Fatalf("retry changed commitment: %+v", c)
271		}
272		// 到期前新使用仍成功，证明未确认。
273		if _, err := s.Use("u2", "jia", 1, noon.Add(-time.Second)); err != nil {
274			t.Fatalf("new use before expiry after retry: %v", err)
275		}
276		// 对照：新使用编号在到期时刻确认并拒绝。
277		if _, err := s.Use("u3", "jia", 1, noon); !errors.Is(err, ErrCommitmentClosed) {
278			t.Fatalf("fresh use at expiry: got %v", err)
279		}
280	}
281	
282	// TestExpiredUseRetryReturnsFirstAtEarlierTime 验证已确认到期后，原样使用
283	// 重试即使传入更早时刻也只返回首次结果，不重新开放、不再次扣减。
284	func TestExpiredUseRetryReturnsFirstAtEarlierTime(t *testing.T) {
285		s := expStore(t, 5)
286		noon := t0.Add(10 * day)
287		before := noon.Add(-time.Minute)
288		after := noon.Add(time.Minute)
289		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
290			t.Fatalf("reserve: %v", err)
291		}
292		if _, err := s.Use("u1", "jia", 2, before); err != nil {
293			t.Fatalf("use: %v", err)
294		}
295		// 由库存查询确认到期。
296		if _, err := s.PartStatus("part1", after); err != nil {
297			t.Fatalf("part status: %v", err)
298		}
299		// 回退时刻原样重试：仍返回首次结果。
300		u, err := s.Use("u1", "jia", 2, before)
301		if err != nil || u.Quantity != 2 {
302			t.Fatalf("retry after confirmed expiry: %+v err %v", u, err)
303		}
304		c, _ := s.Commitment("jia")
305		if c.Used != 2 || !c.Expired {
306			t.Fatalf("commitment changed: %+v", c)
307		}
308		st, _ := s.PartStatus("part1", before)
309		if st.PhysicalRemaining != 3 || st.ActiveOccupied != 0 {
310			t.Fatalf("stock: %+v, want phys=3 occupied=0", st)
311		}
312		// 回退时刻新使用仍被拒。
313		if _, err := s.Use("u2", "jia", 1, before); !errors.Is(err, ErrCommitmentClosed) {
314			t.Fatalf("new use after rollback: %v", err)
315		}
316	}
317	
318	// TestFailedCallsDoNotConfirmExpiry 验证参数非法或引用对象不存在而提前失败
319	// 的调用，即使传入晚于到期的时刻，也不确认任何承诺到期。
320	func TestFailedCallsDoNotConfirmExpiry(t *testing.T) {
321		s := expStore(t, 5)
322		noon := t0.Add(10 * day)
323		before := noon.Add(-time.Minute)
324		after := noon.Add(time.Minute)
325		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
326			t.Fatalf("reserve: %v", err)
327		}
328	
329		// 预留：参数非法。
330		if _, err := s.Reserve("", "r1", "part1", 1, expiryOK, after); !errors.Is(err, ErrInvalidParam) {
331			t.Fatalf("empty commit id: %v", err)
332		}
333		if _, err := s.Reserve("x1", "r1", "part1", 0, expiryOK, after); !errors.Is(err, ErrInvalidParam) {
334			t.Fatalf("zero quantity: %v", err)
335		}
336		if _, err := s.Reserve("x2", "r1", "part1", 1, before, after); !errors.Is(err, ErrInvalidParam) {
337			t.Fatalf("past expiry: %v", err)
338		}
339		// 预留：引用对象不存在。
340		if _, err := s.Reserve("x3", "rMissing", "part1", 1, expiryOK, after); !errors.Is(err, ErrNotFound) {
341			t.Fatalf("unknown request: %v", err)
342		}
343		if _, err := s.Reserve("x4", "r1", "partMissing", 1, expiryOK, after); !errors.Is(err, ErrNotFound) {
344			t.Fatalf("unknown part: %v", err)
345		}
346		// 使用：参数非法 / 承诺不存在。
347		if _, err := s.Use("", "jia", 1, after); !errors.Is(err, ErrInvalidParam) {
348			t.Fatalf("empty usage id: %v", err)
349		}
350		if _, err := s.Use("y1", "jia", 0, after); !errors.Is(err, ErrInvalidParam) {
351			t.Fatalf("zero usage quantity: %v", err)
352		}
353		if _, err := s.Use("y2", "cMissing", 1, after); !errors.Is(err, ErrNotFound) {
354			t.Fatalf("unknown commitment: %v", err)
355		}
356		// 查询：引用对象不存在。
357		if _, err := s.PartStatus("partMissing", after); !errors.Is(err, ErrNotFound) {
358			t.Fatalf("unknown part status: %v", err)
359		}
360		if _, err := s.RequestView("rMissing", after); !errors.Is(err, ErrNotFound) {
361			t.Fatalf("unknown request view: %v", err)
362		}
363	
364		// 甲始终未确认：较早时刻仍有效、占用五件，新使用成功。
365		st, _ := s.PartStatus("part1", before)
366		if st.ActiveOccupied != 5 || st.Committable != 0 {
367			t.Fatalf("failed calls released occupancy: %+v", st)
368		}
369		if d, _ := detailByID(st, "jia"); d.Status != CommitmentActive {
370			t.Fatalf("jia status = %q, want active", d.Status)
371		}
372		if _, err := s.Use("ok", "jia", 1, before); err != nil {
373			t.Fatalf("jia closed by a non-confirming failed call: %v", err)
374		}
375	}
376	
377	// TestCanceledStaysCanceled 验证已取消的承诺不会被确认成 expired：晚时刻、
378	// 早时刻都显示 canceled，占用始终为零，重复取消不产生数量变化。
379	func TestCanceledStaysCanceled(t *testing.T) {
380		s := expStore(t, 5)
381		noon := t0.Add(10 * day)
382		before := noon.Add(-time.Minute)
383		after := noon.Add(time.Minute)
384		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
385			t.Fatalf("reserve: %v", err)
386		}
387		if _, err := s.Use("u1", "jia", 2, before); err != nil {
388			t.Fatalf("use: %v", err)
389		}
390		if _, err := s.Cancel("jia", before); err != nil {
391			t.Fatalf("cancel: %v", err)
392		}
393	
394		for _, tm := range []time.Time{after, before} {
395			st, err := s.PartStatus("part1", tm)
396			if err != nil {
397				t.Fatalf("part status: %v", err)
398			}
399			d, _ := detailByID(st, "jia")
400			if d.Status != CommitmentCanceled {
401				t.Fatalf("at %v status = %q, want canceled", tm, d.Status)
402			}
403			if st.ActiveOccupied != 0 || st.Committable != 3 || st.PhysicalRemaining != 3 {
404				t.Fatalf("at %v stock = %+v, want phys=3 occupied=0 committable=3", tm, st)
405			}
406		}
407		c, _ := s.Commitment("jia")
408		if !c.Canceled || c.Expired {
409			t.Fatalf("canceled commitment marked expired: %+v", c)
410		}
411		// 重复取消不释放更多、不改变标记。
412		if _, err := s.Cancel("jia", after); err != nil {
413			t.Fatalf("repeat cancel: %v", err)
414		}
415		c2, _ := s.Commitment("jia")
416		if !c2.Canceled || c2.Expired || c2.Used != 2 {
417			t.Fatalf("repeat cancel changed commitment: %+v", c2)
418		}
419		// 新使用（无论时刻）一律拒绝。
420		if _, err := s.Use("u2", "jia", 1, before); !errors.Is(err, ErrCommitmentClosed) {
421			t.Fatalf("use canceled at earlier time: %v", err)
422		}
423	}
424	
425	// TestExpiryConfirmationAppendsNoHistory 验证确认到期不覆盖预留历史，
426	// 也不追加到期历史。
427	func TestExpiryConfirmationAppendsNoHistory(t *testing.T) {
428		s := expStore(t, 5)
429		noon := t0.Add(10 * day)
430		before := noon.Add(-time.Minute)
431		after := noon.Add(time.Minute)
432		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
433			t.Fatalf("reserve: %v", err)
434		}
435		if _, err := s.Reserve("yi", "r2", "part1", 5, expiryOK, after); err != nil {
436			t.Fatalf("reserve yi: %v", err)
437		}
438		// 多轮确认到期：库存查询、请求查询、被拒使用。
439		if _, err := s.PartStatus("part1", before); err != nil {
440			t.Fatalf("part status: %v", err)
441		}
442		if _, err := s.RequestView("r1", before); err != nil {
443			t.Fatalf("request view: %v", err)
444		}
445		if _, err := s.Use("u-jia", "jia", 1, before); !errors.Is(err, ErrCommitmentClosed) {
446			t.Fatalf("use jia: %v", err)
447		}
448		h1, _ := s.RequestHistory("r1")
449		if len(h1) != 1 || !h1[0].Success || h1[0].CommitID != "jia" {
450			t.Fatalf("r1 history = %+v, want single jia success", h1)
451		}
452		if h1[0].StockBasis == nil || h1[0].StockBasis.PhysicalRemaining != 5 ||
453			h1[0].StockBasis.ActiveOccupied != 0 || h1[0].StockBasis.Committable != 5 {
454			t.Fatalf("first stock basis overwritten: %+v", h1[0].StockBasis)
455		}
456		h2, _ := s.RequestHistory("r2")
457		if len(h2) != 1 || !h2[0].Success || h2[0].CommitID != "yi" {
458			t.Fatalf("r2 history = %+v, want single yi success", h2)
459		}
460	}
461	
462	// TestNewReserveAtEarlierTimeRejudgesFresh 验证两点：已确认到期的承诺在较早
463	// 时刻的新预留核算中不复活；保修资格只按本次时刻判断，不被此前较大的历史
464	// 时刻替换。
465	func TestNewReserveAtEarlierTimeRejudgesFresh(t *testing.T) {
466		s := expStore(t, 5)
467		jiaExpiry := t0.Add(12 * day)
468		// 第十一天预留甲，第十二天到期。
469		if _, err := s.Reserve("jia", "r1", "part1", 5, jiaExpiry, t0.Add(11*day)); err != nil {
470			t.Fatalf("reserve jia: %v", err)
471		}
472		// 第三十一天（请求此时已过保）库存查询：确认甲到期。
473		st, err := s.PartStatus("part1", t0.Add(31*day))
474		if err != nil {
475			t.Fatalf("part status: %v", err)
476		}
477		if d, _ := detailByID(st, "jia"); d.Status != CommitmentExpired {
478			t.Fatalf("jia = %q, want expired", d.Status)
479		}
480		// 回到第十一天（保修期内）为同一请求新预留五件：资格按第十一天判合格；
481		// 甲虽在其到期时刻之前，但已确认到期，不复活、不占用，乙预留成功。
482		if _, err := s.Reserve("bing", "r1", "part1", 5, expiryOK, t0.Add(11*day)); err != nil {
483			t.Fatalf("reserve bing at earlier eligible time: %v", err)
484		}
485		early, _ := s.PartStatus("part1", t0.Add(11*day))
486		if early.ActiveOccupied != 5 || early.Committable != 0 {
487			t.Fatalf("early stock = %+v, want occupied=5 committable=0", early)
488		}
489		dj, _ := detailByID(early, "jia")
490		db, _ := detailByID(early, "bing")
491		if dj.Status != CommitmentExpired {
492			t.Fatalf("jia resurrected at earlier time: %q", dj.Status)
493		}
494		if db.Status != CommitmentActive || db.RemainingQuantity != 5 {
495			t.Fatalf("bing not active at earlier time: %+v", db)
496		}
497	}
498	
499	// TestNewReserveStockMathConfirmsEvenWhenReserveFails 验证引用有效的新预留
500	// 即使因资格不合格或库存不足而失败，其库存核算仍确认该备件到期承诺；且
501	// 库存依据记录的是确认释放后的可承诺量。
502	func TestNewReserveStockMathConfirmsEvenWhenReserveFails(t *testing.T) {
503		s := expStore(t, 5)
504		// 第三个请求命中除外代码，始终不合格。
505		if err := s.SubmitRequest("r3", "p1", "FAULTX"); err != nil {
506			t.Fatalf("submit r3: %v", err)
507		}
508		noon := t0.Add(10 * day)
509		before := noon.Add(-time.Minute)
510		after := noon.Add(time.Minute)
511		// 甲占满五件。
512		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
513			t.Fatalf("reserve jia: %v", err)
514		}
515	
516		// 晚时刻为不合格请求预留：库存核算先确认甲到期（释放五件），随后资格拒绝。
517		if _, err := s.Reserve("bad1", "r3", "part1", 1, expiryOK, after); !errors.Is(err, ErrIneligible) {
518			t.Fatalf("ineligible reserve: got %v", err)
519		}
520		// 回退时刻：甲已永久释放。
521		st1, _ := s.PartStatus("part1", before)
522		if st1.ActiveOccupied != 0 || st1.Committable != 5 {
523			t.Fatalf("ineligible reserve did not confirm expiry: %+v", st1)
524		}
525	
526		// 另一仓库：合格请求但库存不足（要求超过五件），核算同样确认到期，
527		// 失败记录的库存依据反映释放后的可承诺量。
528		s2 := expStore(t, 5)
529		if _, err := s2.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
530			t.Fatalf("reserve jia: %v", err)
531		}
532		if _, err := s2.Reserve("big", "r2", "part1", 6, expiryOK.Add(2*day), after); !errors.Is(err, ErrInsufficientStock) {
533			t.Fatalf("over-stock reserve: got %v, want ErrInsufficientStock", err)
534		}
535		h, _ := s2.RequestHistory("r2")
536		if len(h) != 1 || h[0].Error != HistoryErrorInsufficientStock ||
537			h[0].StockBasis == nil || h[0].StockBasis.ActiveOccupied != 0 ||
538			h[0].StockBasis.Committable != 5 {
539			t.Fatalf("insufficient-stock record basis: %+v", h)
540		}
541		st2, _ := s2.PartStatus("part1", before)
542		if st2.ActiveOccupied != 0 || st2.Committable != 5 {
543			t.Fatalf("insufficient-stock reserve did not confirm expiry: %+v", st2)
544		}
545	}
546	
547	// TestRequestViewEligibilityUsesCurrentTimeAfterConfirmation 验证确认到期不
548	// 改变资格规则：曾用较大（过保）时刻查询确认到期，回退到保修期内查询时，
549	// 资格仍按本次较早时刻判合格，不被历史大时刻替换。
550	func TestRequestViewEligibilityUsesCurrentTimeAfterConfirmation(t *testing.T) {
551		s := expStore(t, 5)
552		noon := t0.Add(10 * day)
553		afterWarranty := t0.Add(31 * day) // 第 31 天：已过保。
554		withinWarranty := t0.Add(11 * day)
555		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, t0.Add(9*day)); err != nil {
556			t.Fatalf("reserve jia: %v", err)
557		}
558		// 过保时刻查询：确认甲到期，资格不合格。
559		v1, err := s.RequestView("r1", afterWarranty)
560		if err != nil {
561			t.Fatalf("view after warranty: %v", err)
562		}
563		if v1.Eligibility.Eligible {
564			t.Fatalf("expected ineligible at day 31: %+v", v1.Eligibility)
565		}
566		// 回退到保修期内：甲保持到期，但资格按本次时刻判合格。
567		v2, err := s.RequestView("r1", withinWarranty)
568		if err != nil {
569			t.Fatalf("view within warranty: %v", err)
570		}
571		if !v2.Eligibility.Eligible || len(v2.Eligibility.Reasons) != 0 {
572			t.Fatalf("eligibility not re-judged at earlier time: %+v", v2.Eligibility)
573		}
574		if v2.Commitments[0].Status != CommitmentExpired {
575			t.Fatalf("jia status = %q, want expired", v2.Commitments[0].Status)
576		}
577	}
578	
579	// TestPartiallyUsedExpiredOnlyReleasesRemainder 验证到期只释放未用部分：
580	// 甲用掉两件后到期，实物只剩三件、可再承诺三件，无法按五件重复预留。
581	func TestPartiallyUsedExpiredOnlyReleasesRemainder(t *testing.T) {
582		s := expStore(t, 5)
583		noon := t0.Add(10 * day)
584		before := noon.Add(-time.Minute)
585		after := noon.Add(time.Minute)
586		if _, err := s.Reserve("jia", "r1", "part1", 5, noon, before); err != nil {
587			t.Fatalf("reserve jia: %v", err)
588		}
589		if _, err := s.Use("u1", "jia", 2, before); err != nil {
590			t.Fatalf("use jia: %v", err)
591		}
592		// 到期后乙只能预留剩余实物三件。
593		if _, err := s.Reserve("yi", "r2", "part1", 3, expiryOK, after); err != nil {
594			t.Fatalf("reserve yi 3: %v", err)
595		}
596		if _, err := s.Reserve("bing", "r2", "part1", 1, expiryOK.Add(time.Hour), after); !errors.Is(err, ErrInsufficientStock) {
597			t.Fatalf("reserve bing 1: got %v, want ErrInsufficientStock", err)
598		}
599		// 较早时刻回退查询：仍只有乙占用三件。
600		st, _ := s.PartStatus("part1", before)
601		if st.PhysicalRemaining != 3 || st.ActiveOccupied != 3 || st.Committable != 0 {
602			t.Fatalf("rollback stock = %+v, want phys=3 occupied=3 committable=0", st)
603		}
604	}
605

